# Parse dates with multiple formats
import pandas as pd

def parse_year(s):
    if not isinstance(s, str):
        return None
    for fmt in ['%Y-%m-%d %H:%M:%S', '%B %d, %Y at %I:%M %p', '%d %b %Y, %H:%M']:
        try:
            return pd.to_datetime(s, format=fmt).year
        except Exception:
            pass
    # fallback
    try:
        return pd.to_datetime(s, errors='coerce').year
    except Exception:
        return None

df['year'] = df['date'].apply(parse_year)
print(df['year'].value_counts(dropna=False).sort_index())
print("NaN count:", df['year'].isna().sum())

import ast

def truthy(v):
    if v is True:
        return True
    if isinstance(v, str) and v.strip() in {'True', 'true'}:
        return True
    return False

def business_parking_any(v):
    if v is None:
        return False
    parsed = None
    if isinstance(v, dict):
        parsed = v
    elif isinstance(v, str):
        try:
            parsed = ast.literal_eval(v)
        except Exception:
            # fallback: substring check
            return 'True' in v
    if isinstance(parsed, dict):
        return any(truthy(x) for x in parsed.values())
    return False

qualifying = []
bike_only, bp_only, both = 0, 0, 0
for d in docs:
